/**
 * Transposes a matrix
 * @param {number[][]} m - Matrix to transpose
 * @returns {number[][]} Transposed matrix
 */
function transpose(m) {
  // Check if matrix is empty
  if (m.length === 0) {
    throw new Error("Cannot transpose empty matrix");
  }

  // Check if rows have the same length
  const rows = m.length;
  const cols = m[0].length;

  for (let i = 0; i < rows; i++) {
    if (m[i].length !== cols) {
      throw new Error("Matrix rows must have the same length");
    }
  }

  // Perform transpose
  const result = [];
  for (let i = 0; i < cols; i++) {
    result[i] = [];
    for (let j = 0; j < rows; j++) {
      result[i][j] = m[j][i];
    }
  }

  return result;
}

/**
 * Creates an identity matrix of size n
 * @param {number} n - Size of the identity matrix
 * @returns {number[][]} Identity matrix of size n
 */
function identity(n) {
  // Check if n is valid
  if (n <= 0 || !Number.isInteger(n)) {
    throw new Error("Matrix size must be a positive integer");
  }

  // Create identity matrix
  const result = [];
  for (let i = 0; i < n; i++) {
    result[i] = [];
    for (let j = 0; j < n; j++) {
      result[i][j] = (i === j) ? 1 : 0;
    }
  }

  return result;
}

module.exports = { add, multiply, transpose, identity };

